import{_ as t,o as a,c as r,a2 as s}from"./chunks/framework.CdvW4CUT.js";const p=JSON.parse('{"title":"Restarts: pausing and resume","description":"","frontmatter":{},"headers":[],"relativePath":"reboots.md","filePath":"reboots.md"}'),o={name:"reboots.md"};function n(i,e,d,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="restarts-pausing-and-resume" tabindex="-1">Restarts: pausing and <code>resume</code> <a class="header-anchor" href="#restarts-pausing-and-resume" aria-label="Permalink to &quot;Restarts: pausing and `resume`&quot;">​</a></h1><p>Some installs need the machine to restart before the next step can work. ripeat notices, stops cleanly, and lets you carry on afterwards. It does not restart the machine and does not set anything up to run by itself after a restart.</p><h2 id="how-it-notices" tabindex="-1">How it notices <a class="header-anchor" href="#how-it-notices" aria-label="Permalink to &quot;How it notices&quot;">​</a></h2><p>After each install step ripeat asks the OS whether a restart is now pending. Only a restart that <strong>appeared during the run</strong> counts; one that was already waiting before ripeat started is not ripeat&#39;s doing and does not stop anything.</p><table tabindex="0"><thead><tr><th>OS</th><th>A restart is pending when</th></tr></thead><tbody><tr><td>Linux</td><td><code>/var/run/reboot-required</code> exists (Debian, Ubuntu), or <code>needs-restarting -r</code> reports it (Fedora family, when that tool is installed)</td></tr><tr><td>Windows</td><td>the Component Based Servicing <code>RebootPending</code> key, the Windows Update <code>RebootRequired</code> key, or <code>PendingFileRenameOperations</code> is set</td></tr><tr><td>macOS</td><td>never reported (not supported yet)</td></tr></tbody></table><h2 id="what-happens-during-an-install" tabindex="-1">What happens during an install <a class="header-anchor" href="#what-happens-during-an-install" aria-label="Permalink to &quot;What happens during an install&quot;">​</a></h2><ul><li><strong>A restart appears and more work remains:</strong> the run stops after that step, its status becomes <code>needs_reboot</code> (see <code>ripeat history</code>), and ripeat tells you to restart and run <code>ripeat resume</code>. Nothing is undone, and the steps done so far stay recorded.</li><li><strong>A restart appears after the last step:</strong> the run completes and ripeat says a restart is needed to finish.</li><li><strong><code>upgrade</code>:</strong> just says so at the end; it never pauses.</li></ul><h2 id="ripeat-resume-force-dry-run" tabindex="-1"><code>ripeat resume [--force] [--dry-run]</code> <a class="header-anchor" href="#ripeat-resume-force-dry-run" aria-label="Permalink to &quot;`ripeat resume [--force] [--dry-run]`&quot;">​</a></h2><p>Carries on the paused install with the same tools, versions and <code>--scope</code> (and <code>ripeat.lock</code>, if present). Steps that already happened are skipped, because they are managed by now.</p><ul><li>If a restart is still pending, resume refuses and keeps the pause. <code>--force</code> carries on anyway.</li><li>If you already said yes to the plan&#39;s HIGH risk (<a href="./assess">Risk and <code>assess</code></a>) before the pause, resume does not ask again.</li><li>With nothing paused it prints &quot;Nothing to resume.&quot;</li><li>If the resumed install fails it is rolled back like any install, and the pause stays recorded so you can retry.</li><li><code>--dry-run</code> shows what it would install.</li></ul><h2 id="rolling-back" tabindex="-1">Rolling back <a class="header-anchor" href="#rolling-back" aria-label="Permalink to &quot;Rolling back&quot;">​</a></h2><p>A paused run can be rolled back like any other (<code>ripeat rollback</code>), and after a resume the two runs are undone newest first (<a href="./install-and-rollback">Install, uninstall, rollback</a>).</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>Resume is manual. Boxstarter-style automatic continuation after the restart would need a scheduled task or service, which is a standing change to your machine, so ripeat does not create one.</li><li>The Windows detection has never run on a real machine (<a href="./platforms">What has been verified</a>). <code>PendingFileRenameOperations</code> is also set on some machines for unrelated reasons; because only newly appeared restarts count, this does not stop a run.</li></ul>',14)])])}const m=t(o,[["render",n]]);export{p as __pageData,m as default};
